pub fn containsNonBmpCodePoint(text: []const u8) bool {
        var iter = CodepointIterator.init(text);
        _ = &iter;
        var curs = CodepointIterator.Cursor;
        _ = &curs;
        while (iter.next((&curs))) {
            if ((curs.c > 65535)) {
                return true;
            }
        }
        return false;
}

pub fn containsNonBmpCodePointOrIsInvalidIdentifier(text: []const u8) bool {
        var iter = CodepointIterator.init(text);
        _ = &iter;
        var curs = CodepointIterator.Cursor;
        _ = &curs;
        if ((!iter.next((&curs)))) {
            return true;
        }
        if (((curs.c > 65535) or (!js_lexer.isIdentifierStart(curs.c)))) {
            return true;
        }
        while (iter.next((&curs))) {
            if (((curs.c > 65535) or (!js_lexer.isIdentifierContinue(curs.c)))) {
                return true;
            }
        }
        return false;
}

pub fn decodeWTF8RuneT(p: *const [4]u8, len: u3_fast, comptime T: type, comptime zero: T) T {
        if ((len == 0)) {
            return zero;
        }
        if ((len == 1)) {
            return p[0];
        }
        return decodeWTF8RuneTMultibyte(p, len, T, zero);
}

pub fn codepointSize(comptime R: type, r: R) u3_fast {
        return (switch (r) {
0...127 => 1,
192...223 => 2,
224...239 => 3,
240...247 => 4,
else => 0,
});
}

pub fn convertUTF16ToUTF8(list_: std.array_list.Managed(u8), utf16: []const u16) OOM!std.array_list.Managed(u8) {
        var list = list_;
        _ = &list;
        const result = bun.simdutf.convert.utf16.to.utf8.with_errors.le(utf16, list.allocatedSlice());
        if ((result.status == .surrogate)) {
            return toUTF8ListWithTypeBun((&list), utf16, false);
        }
        list.items.len = result.count;
        return list;
}

pub fn convertUTF16ToUTF8Append(list: *std.array_list.Managed(u8), utf16: []const u16) OOM!void {
        const result = bun.simdutf.convert.utf16.to.utf8.with_errors.le(utf16, list.unusedCapacitySlice());
        if ((result.status == .surrogate)) {
            _ = try toUTF8ListWithTypeBun(list, utf16, false);
            return;
        }
        list.items.len = (list.items.len + result.count);
}

pub fn toUTF8AllocWithTypeWithoutInvalidSurrogatePairs(allocator: std.mem.Allocator, utf16: []const u16) OOM![]u8 {
        return toUTF8AllocWithType(allocator, utf16);
}

pub fn toUTF8AllocWithType(allocator: std.mem.Allocator, utf16: []const u16) OOM![]u8 {
        if (bun.FeatureFlags.use_simdutf) {
            const length = bun.simdutf.length.utf8.@"from".utf16.le(utf16);
            var list = try std.array_list.Managed(u8).initCapacity(allocator, (length + 16));
            _ = &list;
            list = try convertUTF16ToUTF8(list, utf16);
            return list.toOwnedSlice();
        }
        var list = try std.array_list.Managed(u8).initCapacity(allocator, utf16.len);
        _ = &list;
        list = try toUTF8ListWithType(list, utf16);
        return list.toOwnedSlice();
}

pub fn toUTF8ListWithType(list_: std.array_list.Managed(u8), utf16: []const u16) OOM!std.array_list.Managed(u8) {
        if (bun.FeatureFlags.use_simdutf) {
            var list = list_;
            _ = &list;
            const length = bun.simdutf.length.utf8.@"from".utf16.le(utf16);
            _ = try list.ensureTotalCapacityPrecise((length + 16));
            const buf = try convertUTF16ToUTF8(list, utf16);
            return buf;
        }
        _ = @compileError("not implemented");
}

pub fn toUTF8AppendToList(list: *std.array_list.Managed(u8), utf16: []const u16) !void {
        if ((!bun.FeatureFlags.use_simdutf)) {
            _ = @compileError("not implemented");
        }
        const length = bun.simdutf.length.utf8.@"from".utf16.le(utf16);
        _ = try list.ensureUnusedCapacity((length + 16));
        _ = try convertUTF16ToUTF8Append(list, utf16);
}

